import os
import re
from taf.ul.sc.unix_functionality import UnixFunctionality
from taf.ul.sc.util import util
from taf.ul.sc.util.scp import Scp
from taf.ul.sc.epcsim.exceptions import ConfigurationFileException


class Workstation(UnixFunctionality):
    """Class with keywords for EPCSim Workstation."""

    def __init__(self, device_name='EPCSIM_WS', device=None, autoconnect=True, epcsim_dir='/opt/iphy/latest/',
                 get_device=False):
        """
        :param device_name: Moler device name.
        :param device: Moler device. Initial state should be set to WS
        :param autoconnect: Connect to device after create object.
        """
        super(Workstation, self).__init__(device_name=device_name, device=device,
                                          autoconnect=autoconnect, get_device=get_device)
        self.epcsim_dir = epcsim_dir
        self.config_dir = os.path.join(self.epcsim_dir, 'config')
        self.config_file_info = None
        self.basic_state = 'UNIX_REMOTE'
        self.root_state = 'UNIX_REMOTE_ROOT'

    def upload_configuration(self, config_file, required_files=None, raise_exception=False):
        """
        Upload local configuration files to workstation's configuration directory.

        :param config_file: Path to main configuration file.
        :param required_files: List with paths to additional configuration files required by main config file.
        :param raise_exception: raise exception when scp fail. Otherwise only warning will be visible.
        :return: None
        """
        log_level = 'error' if raise_exception else 'warning'
        files = [config_file]
        if required_files is not None:
            files.extend(required_files)
        for file_path in files:
            util().upload_files(local_dir=os.path.join(os.path.dirname(file_path)),
                                local_file=os.path.basename(file_path),
                                remote_dir=os.path.join('/tmp/config'),
                                remote_device_name=self.name,
                                autogenerate_hops=True,
                                log_level=log_level,
                                timeout=30
                                )
        self.make_directory(self.config_dir)
        cmd_mv = self.device.get_cmd(cmd_name='mv',
                                     cmd_params={'src': os.path.join('/tmp/config/', '*'),
                                                 'dst': self.config_dir})
        cmd_mv(timeout=10)

    def kill_and_start_epcsim(self, edaemon_port, egate_port):
        """
        Kill all epcsim processes, delete logs directory and start edaemon and egate.

        :param edaemon_port: Port for edaemon process.
        :param egate_port: Port for edamon process.
        :return: True if egate started correctly else False.
        """
        self.device.goto_state(self.root_state)

        self.kill_epcsim_processes(login_as_root=False)
        self.delete_logs(login_as_root=False)
        self.start_edaemon(edaemon_port, login_as_root=False)

        self.device.goto_state(self.basic_state)

        return self.start_egate(egate_port)

    def kill_epcsim_processes(self, login_as_root=True):
        """
        Kill all epcsim processes.

        :param login_as_root: login to root before execute command.
        :return: None.
        """
        if login_as_root:
            self.device.goto_state(self.root_state)

        cmd_killall = self.device.get_cmd(cmd_name='killall', cmd_params={
            'name': '-9 edaemon egate eapp sim_mme sim_enb sim_sgw sim_pgw sim_uec'})
        cmd_killall()

        if login_as_root:
            self.device.goto_state(self.basic_state)

    def delete_logs(self, login_as_root=True):
        """
        Delete epcsim logs dir.

        :param login_as_root: login to root before execute command.
        :return: None
        """
        if login_as_root:
            self.device.goto_state(self.root_state)

        cmd_rm = self.device.get_cmd(cmd_name='rm',
                                     cmd_params={'options': '-rf', 'file': os.path.join(self.epcsim_dir, 'logs')})
        cmd_rm()

        if login_as_root:
            self.device.goto_state(self.basic_state)

    def start_edaemon(self, edaemon_port, login_as_root=True):
        """
        Start edaemon process.

        :param edaemon_port: Port for edaemon process.
        :param login_as_root: login to root before execute command.
        :return: None.
        """
        if login_as_root:
            self.device.goto_state(self.root_state)

        cmd_edeamon = self.device.get_cmd(cmd_name='run_script', cmd_params={'script_command': '{} --port {}'.format(
            os.path.join(self.epcsim_dir, 'edaemon'), edaemon_port)})
        cmd_edeamon()

        if login_as_root:
            self.device.goto_state(self.basic_state)

    def start_egate(self, egate_port):
        """
        Start egate process.

        :param egate_port: Port for egate process.
        :return: True if egate started correctly else False.
        """
        script_commnad = '{} --root --port {}'.format(os.path.join(self.epcsim_dir, 'egate'), egate_port)
        cmd_egate = self.device.get_cmd(cmd_name='run_script',
                                        cmd_params={'script_command': script_commnad})
        cmd_egate()

        egate_status = True if self.get_pid_of_processes(script_commnad) else False
        return egate_status

    def get_current_config_file_info(self):  # noqa C901
        """
        Get current config file information.

        :return: Dictionary with configuration file information.
        """
        last_cfg_file = self._get_last_cfg_file()
        if last_cfg_file is not None:
            cfg_file = {}
            cfg_file['name'] = os.path.basename(last_cfg_file)
            cfg_file['location'] = os.path.join(self.epcsim_dir, os.path.dirname(last_cfg_file))
            cfg_file['path'] = os.path.join(self.epcsim_dir, last_cfg_file)
            cfg_file['md5sum'] = self.get_md5sum(path_to_file=cfg_file['path'])
            cfg_file['require_files'] = {}
            lines = self.get_file_content(path_to_file=cfg_file['path'])
            for line in lines:
                require_file = re.search(r'(^\s*(include)\s*"?(\.\/)?(.*\..{3})"?|^\s*(require)\s*[\"\'](.*)[\"\'])', line)
                if require_file:
                    file_info = {}
                    if require_file.group(2):
                        file_info['name'] = os.path.basename(require_file.group(4))
                        file_info['path'] = os.path.join(self.epcsim_dir, require_file.group(4))
                    elif require_file.group(5):
                        file_info['name'] = os.path.basename(require_file.group(6) + '.lua')
                        file_info['path'] = os.path.join(self.epcsim_dir, require_file.group(6) + '.lua')
                    file_info['location'] = os.path.dirname(file_info['path'])
                    file_info['md5sum'] = self.get_md5sum(path_to_file=file_info['path'])
                    cfg_file['require_files'][file_info['name']] = file_info
            self.config_file_info = cfg_file
        if self.config_file_info is not None:
            return self.config_file_info
        else:
            raise ConfigurationFileException('Cannot find current configuration file')

    def _get_last_cfg_file(self):
        last_cfg_file = None
        lines = self.get_file_content(path_to_file=os.path.join(self.epcsim_dir, '.history'))
        for line in lines:
            cfg_file = re.search(r"(cfg|cfg_sim) file=(.*.(cfg|lua))", line)
            if cfg_file:
                last_cfg_file = cfg_file.group(2)
        return last_cfg_file

    def get_config_file(self, config_log_dir, config_dir_to_download=None):
        """
        Copy config files to log directory from EPCsim if available, if not from reconfiguration flag.

        :param config_log_dir: Target location of the config file.
        :param config_dir_to_download: Directory where config files are stored.
        :return: None
        """
        config_file_info = self.get_current_config_file_info()
        if config_dir_to_download is None:
            config_dir = self.config_dir
        else:
            config_dir = config_dir_to_download

        if config_file_info:
            files_to_copy = list(config_file_info['require_files'].keys())
            files_to_copy.append(config_file_info['name'])

            scp = Scp(local_dir=config_log_dir, source_file=','.join(files_to_copy), remote_device_name=self.name,
                      remote_dir=config_dir, autogenerate_hops=True)
            scp.download()
